SELECT item_date AS itemDate, data_type AS dataType, NVL(count_last, 0) AS countLast, NVL(count_current, 0) AS countCurrent, NVL(count_compare, 0) AS countCompare, NVL(amount_last, 0) AS amountLast, NVL(amount_current, 0) AS amountCurrent, NVL(amount_compare, 0) AS amountCompare FROM TR_INPAT_PREPAY_DTL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND data_type = #{dataType}
ORDER BY item_date

SELECT chart_type AS chartType, chart_title AS chartTitle, chart_subtitle AS chartSubtitle, date_range AS dateRange, category, series_name AS seriesName, NVL(data_value, 0) AS dataValue, NVL(compare_value, 0) AS compareValue FROM TR_INPAT_PREPAY_CHT WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND chart_type = #{chartType}
ORDER BY category, series_name
